import { createBridgeRelay } from "@fluid-deck/extension-core";
import { APP_ORIGINS } from "../src/bridge-config.ts";

/**
 * EXT-004 — content-script relay entrypoint (hop 2). Injected at
 * `document_start` on exact app origins only, so it is listening before the
 * web app posts `capture.ready`. All message validation lives in
 * `createBridgeRelay`; this file only supplies the browser surfaces.
 *
 * The nonce is stored in the content script's sessionStorage so it survives a
 * page reload in the same tab. It is regenerated by the web app on every load
 * and re-announced via `capture.ready`.
 */
const RELAY_NONCE_KEY = "fluid-deck:relay-nonce";

export default defineContentScript({
  matches: APP_ORIGINS.map((origin) => `${origin}/*`),
  runAt: "document_start",
  main() {
    // Belt-and-braces: `matches` already restricts injection, but a manifest
    // mistake must never widen the allowlist.
    if (!APP_ORIGINS.some((origin) => origin === location.origin)) return;

    const relay = createBridgeRelay({
      allowedOrigin: location.origin,
      pageWindow: window,
      postToPage: (message, targetOrigin) => window.postMessage(message, targetOrigin),
      sendToBackground: (message) => {
        try {
          void browser.runtime.sendMessage(message).catch(() => undefined);
        } catch {
          // Background restarting; the outbox retries.
        }
      },
      readNonce: () => {
        try {
          return sessionStorage.getItem(RELAY_NONCE_KEY) ?? "";
        } catch {
          return "";
        }
      },
      writeNonce: (nonce) => {
        try {
          sessionStorage.setItem(RELAY_NONCE_KEY, nonce);
        } catch {
          // Privacy mode: keep the nonce in the closure only.
        }
      },
    });

    window.addEventListener("message", (event) => {
      relay.handlePageMessage(event);
    });

    browser.runtime.onMessage.addListener((message) => {
      relay.handleBackgroundMessage(message);
    });
  },
});
